        'actions_row5_does' => 'ടിക്കറ്റിന്റെ ഓഡിറ്റ് ട്രെയിലിലേക്ക് ഒരു ഫ്രീ-ടെക്സ്റ്റ് കുറിപ്പ് ചേർക്കുന്നു. ഇന്റേണൽ &mdash; ഒരിക്കലും അഭ്യർത്ഥിച്ചയാൾക്ക് അയയ്ക്കില്ല.',
        'actions_row5_args' => 'ticket_id, note',
        'actions_row6_does' => 'ടിക്കറ്റിന്റെ മെയിൽബോക്സ് ഉപയോഗിച്ച് ടിക്കറ്റിന്റെ അഭ്യർത്ഥിച്ചയാൾക്ക് (അല്ലെങ്കിൽ ഏത് വിലാസത്തിലേക്കും) ഒരു ഇമെയിൽ അയയ്ക്കുന്നു. മറുപടികൾ സ്വയമേവ ത്രെഡ് ചെയ്യാൻ വിഷയത്തിന് മുന്നിൽ <code>[SDREF:&hellip;]</code> ചേർക്കുന്നു. <strong>ഒരു ടിക്കറ്റ് ഇപ്പോൾ ഐച്ഛികമാണ്</strong> &mdash; പകരം അയയ്ക്കാൻ ഒരു മെയിൽബോക്സ് തിരഞ്ഞെടുക്കുക, ഏതെങ്കിലും ടിക്കറ്റ് നിലവിലുള്ളതിന് മുമ്പ് ഒരു ഫോം ഒരു സമർപ്പണം അംഗീകരിക്കുന്ന വിധം ഇതാണ്. ഒരു ടിക്കറ്റ് ഇല്ലാതെ ഒരു മറുപടി ത്രെഡ് ചെയ്യാൻ ഒന്നുമില്ല, അതിനാൽ എവിടേക്കും പോകാത്ത ഒരു മറുപടിക്ക് ക്ഷണിക്കുന്നതിന് പകരം &ldquo;reply above this line&rdquo; മാർക്കർ ഒഴിവാക്കുന്നു.',
        'actions_row6_args' => 'ticket_id, to, subject, body',
        'actions_row7_does' => 'ഒരു ടാസ്ക് സൃഷ്ടിക്കുന്നു. <code>ticket_id</code> നൽകിയിട്ടുണ്ടെങ്കിൽ സോഴ്സ് ടിക്കറ്റിലേക്ക് സ്വയമേവ ലിങ്ക് ചെയ്യുന്നു. ശൂന്യമാണെങ്കിൽ Status / priority വർക്ക്സ്പേസിന്റെ സ്ഥിരസ്ഥിതികളിലേക്ക് പോകും.',
        'actions_row7_args' => 'title, description, status_id, priority_id, assignee_id, ticket_id',
        'actions_row8_does' => 'ഒരു പുതിയ ടിക്കറ്റ് സൃഷ്ടിക്കുന്നു. <em>"new-starter form &rarr; IT + HR + Facilities tickets"</em> പോലുള്ള ഫാൻ-ഔട്ട് വർക്ക്ഫ്ലോകൾക്ക് ഉപയോഗപ്രദമാണ്. ഇവന്റ് ഒരു <strong>form submission</strong> വഹിക്കുമ്പോൾ, ടിക്കറ്റ് ശരിയായ വിധത്തിൽ സ്വയമേവ ഉയർത്തപ്പെടുന്നു &mdash; അഭ്യർത്ഥിച്ചയാൾ അവരുടെ യഥാർത്ഥ അക്കൗണ്ടുമായി പൊരുത്തപ്പെടുത്തുന്നു, കമ്പനി അതിൽ നിന്ന് എടുക്കുന്നു, ബോഡി ശൂന്യമായി വിട്ടാൽ സമർപ്പിച്ച ഉത്തരങ്ങൾ ഒരു ടേബിളായി നിരത്തുന്നു. നിങ്ങൾ ഇവിടെ സജ്ജമാക്കുന്നത് എന്തും ഇപ്പോഴും വിജയിക്കും; നിങ്ങൾ ശൂന്യമായി വിട്ടത് മാത്രമേ ഫോം പൂരിപ്പിക്കൂ.',
        'actions_row8_args' => 'subject, body, priority_id, department_id, type_id, assigned_analyst_id, from_email, from_name',
        'actions_row9_does' => 'ഒരു എക്സ്റ്റേണൽ URL-ലേക്ക് ഒരു മെസ്സേജ് POST ചെയ്യുന്നു &mdash; Slack, Teams, Discord, PagerDuty, Zapier/Make അല്ലെങ്കിൽ ഇൻകമിംഗ് വെബ്‌ഹുക്ക് സ്വീകരിക്കുന്ന ഏത് സിസ്റ്റത്തിലേക്കും ഇവന്റുകൾ പുഷ് ചെയ്യുക. ഒരു ചാറ്റ് പ്രീസെറ്റ് തിരഞ്ഞെടുക്കുക, Full record അയയ്ക്കുക (REST API പോലെ തന്നെ മുഴുവൻ ഒബ്ജക്റ്റും JSON ആയി), അല്ലെങ്കിൽ നിങ്ങളുടെ സ്വന്തം കസ്റ്റം JSON ബോഡി ടെംപ്ലേറ്റ് ചെയ്യുക. ഐച്ഛികമായ ഒരു HMAC സൈനിംഗ് സീക്രട്ട് പിന്തുണയ്ക്കുന്നു, സേവ് ചെയ്യുന്നതിന് മുമ്പ് എൻഡ്‌പോയിന്റിന്റെ യഥാർത്ഥ പ്രതികരണം കാണിക്കുന്ന ഒരു Send test ബട്ടണും.',
        'actions_row9_args' => 'preset, url, message (presets), body (custom JSON), secret (optional)',
        'actions_note' => 'ഫോമിൽ ഓരോ ആക്ഷന്റെയും ആവശ്യമായ ആർഗ്യുമെന്റുകൾ <code>*</code> കൊണ്ട് അടയാളപ്പെടുത്തിയിരിക്കുന്നു. ആവശ്യമായ ആർഗ്യുമെന്റുകൾ ഇല്ലാത്തത് എക്സിക്യൂഷൻ സമയത്ത് ആക്ഷൻ പരാജയപ്പെടാൻ കാരണമാകുന്നു &mdash; എഞ്ചിൻ പരാജയം എക്സിക്യൂഷൻ വരിയിൽ രേഖപ്പെടുത്തുകയും ബാക്കി ചെയിൻ നിർത്തുകയും ചെയ്യുന്നു.',
        'actions_webhook_callout' => '<strong>The <code>send_webhook</code> action is a big topic of its own</strong> &mdash; chat presets, whole-object &ldquo;Full record&rdquo; payloads, HMAC signing, a Send-test button, background delivery with retries, and a health dashboard. It has a dedicated guide: <a href="help-webhooks.php"><strong>Webhooks guide &rarr;</strong></a>',
        'variables_heading' => 'Variables &mdash; <code>{{path.to.field}}</code>',
        'variables_intro' => 'ഏത് ഫ്രീ-ടെക്സ്റ്റ് ആക്ഷൻ ആർഗ്യുമെന്റിനും അതിനെ ഫയർ ചെയ്ത ഇവന്റിൽ നിന്ന് മൂല്യങ്ങൾ എടുക്കാം. കോഡുകൾ കൈകൊണ്ട് ടൈപ്പ് ചെയ്യേണ്ടതില്ല: വേരിയബിൾ-ഫ്രണ്ട്‌ലി ആയ ഓരോ ഫീൽഡിനും <strong>വശത്ത് തിരയാവുന്ന വേരിയബിളുകളുടെ ലിസ്റ്റ്</strong> ഉള്ള ഒരു വിശാലമായ എഡിറ്റർ തുറക്കുന്ന ഒരു <strong>Edit with variables</strong> ബട്ടൺ ഉണ്ട് — ഒന്നിൽ ക്ലിക്ക് ചെയ്താൽ അത് നിങ്ങളുടെ കർസറിൽ വീഴും. ഓരോ കോഡും അത് സൂചിപ്പിക്കുന്നതിലേക്ക് മാറ്റി ഒരു ലൈവ് പ്രിവ്യൂ പൂർത്തിയായ ടെക്സ്റ്റ് കാണിക്കുന്നു.',
        'variables_scoped' => '<strong>ട്രിഗ്ഗറിന് യഥാർത്ഥത്തിൽ പൂരിപ്പിക്കാൻ കഴിയുന്ന വേരിയബിളുകൾ മാത്രമേ നിങ്ങൾക്ക് എപ്പോഴും വാഗ്ദാനം ചെയ്യൂ.</strong> ഇത് തോന്നുന്നതിനേക്കാൾ പ്രധാനമാണ്: ഒരു കാണാതായ വേരിയബിൾ ഒരു പിശക് ഉയർത്തുന്നില്ല, അത് നിശബ്ദമായി ഒരു <em>ശൂന്യ സ്ട്രിംഗ്</em> ആയി പരിഹരിക്കുന്നു. അതിനാൽ <code>{{ticket.subject}}</code> എന്ന് പറയുന്ന ഒരു മെസ്സേജുള്ള <code>knowledge.published</code>-ലെ ഒരു വർക്ക്ഫ്ലോ പരാജയപ്പെടില്ല — വിഷയം ഉണ്ടാകേണ്ടിടത്ത് അത് ഒരു ശൂന്യത പോസ്റ്റ് ചെയ്യും, നിങ്ങൾക്ക് ഒരിക്കലും അറിയില്ല. ഒരു knowledge ഇവന്റിൽ ടിക്കറ്റ് ഇല്ല, അതിനാൽ പിക്കർ ടിക്കറ്റ് വേരിയബിളുകൾ ഒട്ടും വാഗ്ദാനം ചെയ്യുന്നില്ല, നിങ്ങൾ എന്തായാലും ഒന്ന് ടൈപ്പ് ചെയ്താൽ അത് ശൂന്യമായി വരുമെന്ന് ഫീൽഡ് മുന്നറിയിപ്പ് നൽകുന്നു.',
        'variables_names' => '<strong>ഐഡിയല്ല, പേര് ഉപയോഗിക്കുക.</strong> <code>{{ticket.priority_id}}</code> <code>4</code> ആയി റെൻഡർ ചെയ്യുന്നു &mdash; നിങ്ങളുടെ Slack ചാനൽ വായിക്കുന്ന ആർക്കും വ്യാഖ്യാനിക്കാൻ കഴിയാത്ത ഒരു നമ്പർ. അതിനാൽ ഓരോ ലുക്കപ്പ് ഫീൽഡിനും വായിക്കാവുന്ന ഒരു ഇരട്ടയുണ്ട്: <code>{{ticket.priority_name}}</code> <strong>Critical</strong> ആയി റെൻഡർ ചെയ്യുന്നു. പിക്കർ പേര് സാധാരണ ചോയ്സായി ലിസ്റ്റ് ചെയ്യുന്നു (<em>Ticket &middot; Priority</em>), നമ്പർ ഒന്നിനെ <em>(id)</em> എന്ന് അടയാളപ്പെടുത്തുന്നു, കാരണം ഒരു വ്യക്തി വായിക്കുന്ന മെസ്സേജിൽ നിങ്ങൾക്ക് വേണ്ടത് മിക്കവാറും എപ്പോഴും പേരാണ്. നിങ്ങൾക്ക് ആവശ്യമുള്ളപ്പോൾ ഐഡികൾ ഇപ്പോഴും അവിടെയുണ്ട് &mdash; ഒരു കണ്ടീഷനായി, അല്ലെങ്കിൽ അവ പ്രതീക്ഷിക്കുന്ന ഒരു സ്വീകരിക്കുന്ന സിസ്റ്റത്തിനായി. ചേഞ്ച് ട്രിഗ്ഗറുകളിൽ നിങ്ങൾക്ക് <code>{{old_priority_name}}</code> / <code>{{new_priority_name}}</code> കൂടി ലഭിക്കും, അതിനാൽ "escalated from High to Critical" സ്വയം എഴുതും.',
        'variables_number' => '<strong>റോ ഐഡിയല്ല, റഫറൻസ് ക്വോട്ട് ചെയ്യുക.</strong> <code>{{ticket.id}}</code> ഇന്റേണൽ ഡാറ്റാബേസ് ഐഡിയാണ് (<code>83</code>) &mdash; ഒരു അഭ്യർത്ഥിച്ചയാൾക്ക് അർത്ഥശൂന്യമാണ്. <code>{{ticket.number}}</code> അവർ യഥാർത്ഥത്തിൽ നിങ്ങളോട് തിരികെ ക്വോട്ട് ചെയ്യുന്ന റഫറൻസ് ആണ് (<code>ETC-623-64409</code>), ഒരു ഇമെയിൽ വിഷയത്തിലോ ചാറ്റ് അലേർട്ടിലോ ഇത് വേണം. <code>{{problem.number}}</code>-നും ഇതുതന്നെ. <strong>ഒരു അപവാദം:</strong> ഒരു <em>Ticket ID</em> ആക്ഷൻ ആർഗ്യുമെന്റ് <code>{{ticket.id}}</code> ആയി തുടരണം &mdash; ആ ഫീൽഡ് <em>ഏത് റെക്കോർഡിലാണ് പ്രവർത്തിക്കേണ്ടത്</em> എന്ന് എഞ്ചിനോട് പറയുന്നു, അത് റോ ഐഡി പ്രകാരം അത് നോക്കുന്നു. ഒരു വ്യക്തി വായിക്കുന്ന വാക്കുകളിൽ നമ്പർ ഉപയോഗിക്കുക; പ്ലംബിംഗിൽ ഐഡി വിടുക.',
        'variables_full' => 'ഒരു ട്രിഗ്ഗർ മുഴുവൻ റെക്കോർഡ് വഹിക്കുന്നിടത്ത്, നിങ്ങൾക്ക് <code>{{&lt;object&gt;.full}}</code> കൂടി ലഭിക്കും &mdash; ഉദാ. <code>{{ticket.full}}</code> &mdash; ഇത് REST API തിരികെ നൽകുന്ന അതേ രൂപത്തിൽ മുഴുവൻ റെക്കോർഡും JSON ആയി ഉൾച്ചേർക്കുന്നു. <code>{{event}}</code> എപ്പോഴും ഫയർ ചെയ്ത ട്രിഗ്ഗറിന്റെ പേരിലേക്ക് പരിഹരിക്കുന്നു.',
        'variables_common' => 'ടിക്കറ്റ് ട്രിഗ്ഗറുകൾക്കുള്ള സാധാരണ വേരിയബിളുകൾ:',
        'variables_li1' => '<code>{{ticket.id}}</code>, <code>{{ticket.subject}}</code>, <code>{{ticket.priority_id}}</code>, <code>{{ticket.status_id}}</code>',
        'variables_li2' => '<code>{{ticket.department_id}}</code>, <code>{{ticket.type_id}}</code>, <code>{{ticket.assigned_analyst_id}}</code>',
        'variables_li3' => '<code>{{ticket.owner_id}}</code>, <code>{{ticket.created_by}}</code>, <code>{{ticket.requester_email}}</code>',
        'variables_li4' => '<code>ticket.status_changed</code> / <code>ticket.priority_changed</code>-ന്: <code>{{old_status_id}}</code>, <code>{{new_status_id}}</code>, <code>{{old_priority_id}}</code>, <code>{{new_priority_id}}</code> കൂടി',
        'variables_li5' => '<code>ticket.assigned</code>-ന്: <code>{{analyst_id}}</code>, <code>{{team_id}}</code> കൂടി',
        'variables_tip' => '<strong>മികച്ച രീതി:</strong> ആക്ഷന്റെ <code>ticket_id</code> ഫീൽഡുകളിൽ, ഒരു നിശ്ചിത ഐഡി ടൈപ്പ് ചെയ്യുന്നതിനുപകരം സ്ഥിരസ്ഥിതി <code>{{ticket.id}}</code> വിടുക &mdash; അങ്ങനെയെങ്കിൽ ഏത് ടിക്കറ്റാണോ ട്രിഗർ ചെയ്തത് അതിലാണ് വർക്ക്ഫ്ലോ പ്രവർത്തിക്കുന്നത്, ഒരു നിശ്ചിതത്തിലല്ല.',
        'variables_chain_heading' => 'നേരത്തെയുള്ള ഒരു ആക്ഷൻ ഉൽപ്പാദിപ്പിച്ചത് ഉപയോഗിക്കൽ',
        'variables_chain_intro' => 'ആക്ഷനുകൾ ക്രമത്തിൽ റൺ ആകുന്നു, പിന്നീടുള്ള ഒന്നിന് നേരത്തെയുള്ള ഒന്ന് ചെയ്തതിനെ പരാമർശിക്കാം. ഇതാണ് <em>&ldquo;ഒരു ടിക്കറ്റ് ഉയർത്തുക, എന്നിട്ട് അവരുടെ ടിക്കറ്റ് നമ്പർ വ്യക്തിക്ക് ഇമെയിൽ ചെയ്യുക&rdquo;</em> ഒരു അസാധ്യതയല്ല, ഒറ്റ വർക്ക്ഫ്ലോ ആക്കുന്നത്.',
        'variables_chain_last' => '<code>{{last.ticket_id}}</code> &mdash; ഇതിന് തൊട്ടുമുമ്പുള്ള ആക്ഷൻ എന്ത് ഉൽപ്പാദിപ്പിച്ചോ അത്.',
        'variables_chain_steps' => '<code>{{steps.1.ticket_number}}</code> &mdash; ക്യാൻവാസിൽ അതിനടുത്ത് കാണിച്ചിരിക്കുന്ന നമ്പർ പ്രകാരം, ഒരു നിർദ്ദിഷ്ട ആക്ഷൻ. നിങ്ങൾക്ക് വേണ്ട ആക്ഷൻ നേരിട്ട് മുമ്പുള്ളതല്ലെങ്കിൽ ഇത് ഉപയോഗിക്കുക.',
        'variables_chain_note' => 'ഇവ വർക്ക്ഫ്ലോയുടെ സ്വന്തം ഡാറ്റ ഓവർറൈറ്റ് ചെയ്യാതെ മനഃപൂർവ്വം സ്വന്തം പേരുകൾക്ക് കീഴിൽ ഇരിക്കുന്നു. ഒരു ടിക്കറ്റ് സൃഷ്ടിക്കുന്നത് <code>{{ticket.id}}</code> മാറ്റിസ്ഥാപിച്ചിരുന്നെങ്കിൽ, ഒരു ടിക്കറ്റ് വർക്ക്ഫ്ലോയിലെ പിന്നീടുള്ള ഓരോ സ്റ്റെപ്പും വർക്ക്ഫ്ലോ ഓണാക്കിയ ടിക്കറ്റിന് പകരം നിശബ്ദമായി പുതിയ ടിക്കറ്റിലേക്ക് ചൂണ്ടാൻ തുടങ്ങുമായിരുന്നു.',
        'actions_forms_callout' => '<strong>ഫോമുകൾക്കും ഈ ആക്ഷനുകൾ റൺ ചെയ്യാം.</strong> ഒരു വർക്ക്ഫ്ലോ നിർമ്മിക്കുന്നതിനുപകരം, ഒരു ഫോം തുറന്ന്, അത് സമർപ്പിക്കുമ്പോൾ, അംഗീകരിക്കുമ്പോൾ അല്ലെങ്കിൽ നിരസിക്കുമ്പോൾ എന്ത് സംഭവിക്കണം എന്ന് പറയാൻ അതിന്റെ <strong>What happens next</strong> ടാബ് ഉപയോഗിക്കുക. ഇത് അതേ എഞ്ചിനും അതേ ആക്ഷനുകളുമാണ്, റണ്ണുകൾ അതേ എക്സിക്യൂഷൻ ലോഗിൽ പ്രത്യക്ഷപ്പെടുന്നു &mdash; ഫോം എഡിറ്റർ ആ ഒരു ഫോമിലേക്ക് സ്കോപ്പ് ചെയ്ത ഒരു രണ്ടാമത്തെ വഴി മാത്രമാണ്. ഒരു റൂൾ പല ഫോമുകളിലും വ്യാപിക്കേണ്ടതുണ്ടെങ്കിൽ ഇവിടെ ഒരു വർക്ക്ഫ്ലോ നിർമ്മിക്കുക.',
        'ai_heading' => 'AI സഹ-രചയിതാവ്',
        'ai_intro' => 'ടൂൾബാറിലെ <strong>AI co-author</strong> ക്ലിക്ക് ചെയ്ത് വർക്ക്ഫ്ലോ പ്ലെയിൻ ഇംഗ്ലീഷിൽ വിവരിക്കുക. AI ഒരു ഘടനാപരമായ നിർദ്ദേശം തിരികെ നൽകുന്നു &mdash; trigger, conditions, actions &mdash; നിങ്ങൾക്ക് ക്യാൻവാസിലേക്ക് <em>Apply</em> ചെയ്യാം അല്ലെങ്കിൽ <em>Discard</em> ചെയ്യാം.',
        'ai_examples' => 'നന്നായി പ്രവർത്തിക്കുന്ന ഉദാഹരണങ്ങൾ:',
        'ai_ex1' => '<em>"ഒരു Critical-മുൻഗണനയുള്ള ടിക്കറ്റ് സൃഷ്ടിക്കപ്പെടുമ്പോൾ, \'P1 &mdash; please respond within 15 minutes\' എന്ന് പറയുന്ന ഒരു കുറിപ്പ് ചേർക്കുക."</em>',
        'ai_ex2' => '<em>"<code>finance@acme.com</code>-ൽ നിന്നുള്ള ഒരു ടിക്കറ്റ് സൃഷ്ടിക്കപ്പെടുമ്പോൾ, അത് എനിക്ക് അസൈൻ ചെയ്യുകയും മുൻഗണന High ആയി സജ്ജമാക്കുകയും ചെയ്യുക."</em>',
        'ai_ex3' => '<em>"ഒരു ടിക്കറ്റ് അടയ്ക്കുമ്പോൾ, അഭ്യർത്ഥിച്ചയാളെ നന്ദി പറഞ്ഞും ഫീഡ്ബാക്ക് ചോദിച്ചും ഒരു ഇമെയിൽ അയയ്ക്കുക."</em>',
        'ai_catalogue' => 'AI-ക്ക് എഞ്ചിന്റെ പൂർണ്ണ കാറ്റലോഗ് അറിയാം &mdash; ഓരോ trigger, condition operator, action, ലഭ്യമായ lookup-table മൂല്യങ്ങൾ &mdash; അതിനാൽ യഥാർത്ഥത്തിൽ പ്രവർത്തിക്കുന്ന കാര്യങ്ങൾ മാത്രമേ ഇതിന് നിർദ്ദേശിക്കാൻ കഴിയൂ. നിലവിലുള്ള ഒരു വർക്ക്ഫ്ലോയിൽ നിങ്ങൾ ഇറ്ററേറ്റ് ചെയ്യുകയാണെങ്കിൽ (<em>"now only match Finance"</em> / <em>"add an action to log the ticket id"</em>) അത് വീണ്ടും തുടങ്ങുന്നതിനുപകരം ക്യാൻവാസിലുള്ളത് എഡിറ്റ് ചെയ്യുന്നു.',
        'ai_config' => '<strong>Workflow &rarr; Settings &rarr; AI</strong>-ന് കീഴിൽ provider (Anthropic / OpenAI), model, API key എന്നിവ കോൺഫിഗർ ചെയ്യുക. ബില്ലിംഗും ആക്സസും ഗ്രാനുലാർ ആകാൻ കീകൾ ഓരോ മൊഡ്യൂളിനും സംഭരിച്ചിരിക്കുന്നു.',
        'templates_heading' => 'ഒരു ടെംപ്ലേറ്റിൽ നിന്ന് തുടങ്ങുക',
        'templates_intro' => 'Workflows ലിസ്റ്റിലെ <strong>New from template</strong> ബട്ടൺ മിക്ക സർവീസ് ഡെസ്കുകളും ആദ്യം ഓട്ടോമേറ്റ് ചെയ്യുന്ന ജോലികൾക്കുള്ള റെഡിമെയ്ഡ് റെസിപ്പികളുടെ ഒരു ഗാലറി തുറക്കുന്നു &mdash; ഒരു പുതിയ ടിക്കറ്റ് സ്വയമേവ അംഗീകരിക്കൽ, ഒരു P1-ൽ ടീമിനെ അലേർട്ട് ചെയ്യൽ, ഒരു new-starter ഫോം IT, HR, Facilities ടിക്കറ്റുകളിലേക്ക് ഫാൻ ചെയ്യൽ, ഒരു ചേഞ്ച് അംഗീകരിക്കുമ്പോൾ ഒരു ഇംപ്ലിമെന്റേഷൻ ടാസ്ക് ഉയർത്തൽ. അതിൽ നാലെണ്ണം <strong>ടൈം-ബേസ്ഡ്</strong> ആണ്: ഒരു ടിക്കറ്റിന്റെ SLA ബ്രീച്ച് ചെയ്യുന്നതിന് <em>മുമ്പ്</em> അതിനെ എസ്കലേറ്റ് ചെയ്യൽ, ഒന്ന് ബ്രീച്ച് ചെയ്തപ്പോൾ അലേർട്ട് ചെയ്യൽ, ഒരു കരാർ അല്ലെങ്കിൽ ആസ്തി വാറന്റി കാലഹരണപ്പെടാൻ പോകുന്നു എന്ന് ഓർമ്മിപ്പിക്കൽ. ഒന്ന് തിരഞ്ഞെടുക്കുക, അത് നിങ്ങളുടെ വർക്ക്ഫ്ലോകളിലേക്ക് ഒരു സാധാരണ, പൂർണ്ണമായി എഡിറ്റ് ചെയ്യാവുന്ന വർക്ക്ഫ്ലോ ആയി പകർത്തപ്പെടും. അതിനുശേഷം ഇതിൽ പ്രത്യേകതയൊന്നുമില്ല: റീനെയിം ചെയ്യാനും റീവയർ ചെയ്യാനും ഇല്ലാതാക്കാനും നിങ്ങൾക്ക് സ്വാതന്ത്ര്യമുണ്ട്. ഗാലറി <strong>വിഭാഗം</strong> പ്രകാരവും <strong>തിരയൽ</strong> പ്രകാരവും ഫിൽട്ടർ ചെയ്യുന്നു &mdash; ഇത് വിവരണം, ട്രിഗ്ഗർ, ആക്ഷനുകൾ എന്നിവയിലേക്കും എത്തുന്നു, അതിനാൽ പേരിൽ ആ വാക്ക് ഇല്ലെങ്കിലും <em>expiry</em>, <em>slack</em> അല്ലെങ്കിൽ <em>wipe</em> ടൈപ്പ് ചെയ്യുന്നത് റെസിപ്പി കണ്ടെത്തുന്നു.',
        'templates_lookups' => 'ഓരോ ഇൻസ്റ്റാളും അതിന്റേതായ statuses, priorities എന്നിവയ്ക്ക് പേര് നൽകുന്നു, അതിനാൽ ഒരു ടെംപ്ലേറ്റിന് അവ വെറുതെ ഹാർഡ്‌കോഡ് ചെയ്യാൻ കഴിയില്ല. പകരം അത് <em>"ഈ ഇൻസ്റ്റാൾ Closed എന്ന് വിളിക്കുന്നത് എന്തായാലും"</em> എന്ന് പറയുന്നു, പകർത്തുമ്പോൾ ഞങ്ങൾ യഥാർത്ഥ മൂല്യം നോക്കുന്നു. ഞങ്ങൾക്ക് പൊരുത്തപ്പെടുത്താൻ കഴിയാത്തതെന്തും &mdash; നിങ്ങൾക്കില്ലാത്ത ഒരു മുൻഗണന, അല്ലെങ്കിൽ ഒരു Slack webhook URL പോലെ നിങ്ങൾക്ക് മാത്രം അറിയാവുന്ന ഒരു മൂല്യം &mdash; ശൂന്യമായി വിടുകയും എഡിറ്ററിന്റെ മുകളിൽ ഒരു ബാനറിൽ ലിസ്റ്റ് ചെയ്യുകയും ചെയ്യുന്നു, അതിനാൽ ഇപ്പോഴും നിങ്ങളെ ആവശ്യമുള്ളത് എന്താണെന്ന് കൃത്യമായി കാണാം.',
        'templates_scheduled' => 'നാല് ടൈം-ബേസ്ഡ് റെസിപ്പികൾക്കും ഒരു <strong>ഷെഡ്യൂൾഡ് ടാസ്ക്</strong> റൺ ആയിക്കൊണ്ടിരിക്കണം, കാരണം അവ കാത്തിരിക്കുന്നത് ഒരു ഇവന്റ് അല്ല &mdash; ഒരു SLA നിശബ്ദമായി സമയം തീരുമ്പോൾ ആരും ഒന്നും സേവ് ചെയ്യുന്നില്ല, അതിനാൽ ഒരു ജോലി അന്വേഷിച്ച് പോകേണ്ടതുണ്ട്. ക്രോണുകൾ ഷെഡ്യൂൾ ചെയ്തിട്ടില്ലെങ്കിൽ ഈ വർക്ക്ഫ്ലോകൾ ആക്ടീവ് ആയി അവിടെ ഇരിക്കും, ഒരിക്കലും ഫയർ ചെയ്യില്ല. രണ്ട് expiry ഓർമ്മപ്പെടുത്തലുകളും <strong>90, 30, 7, 1 ദിവസങ്ങൾ</strong> മുമ്പ് ഫയർ ചെയ്യും, ഓരോ റെസിപ്പിയും 30-ദിവസത്തേതിലേക്ക് ഫിൽട്ടർ ചെയ്യുന്നു &mdash; എല്ലാ വിൻഡോയിലും അറിയിക്കാൻ ആ കണ്ടീഷൻ മാറ്റുക, അല്ലെങ്കിൽ ഒഴിവാക്കുക. <a href="#triggers">Triggers</a> കാണുക.',
        'templates_callout' => 'ഒരു ക്ലോൺ ചെയ്ത ടെംപ്ലേറ്റ് എപ്പോഴും <strong>ഓഫ് ആയി</strong> എത്തുന്നു. നിങ്ങൾ ഇത് വായിച്ച്, വിടവുകൾ പൂരിപ്പിച്ച്, <em>Active</em> ടിക്ക് ചെയ്യുന്നത് വരെ ഇതിലുള്ളതൊന്നും ഫയർ ചെയ്യില്ല &mdash; ഇത് കൃത്യമായി എന്ത് ചെയ്യുമെന്ന് കാണാൻ ആദ്യം നിങ്ങൾക്ക് <strong>Dry run</strong> ചെയ്യാം.',
        'testing_heading' => 'സേവ് ചെയ്യലും ടെസ്റ്റ് ചെയ്യലും',
        'testing_save' => 'ടൂൾബാറിലെ status pip <em>Unsaved</em> / <em>Saving&hellip;</em> / <em>Saved</em> കാണിക്കുന്നു. നിലനിർത്താൻ <strong>Save</strong> ക്ലിക്ക് ചെയ്യുക. പൂജ്യം ആക്ഷനുകളുള്ള പുരോഗതിയിലുള്ള ഡ്രാഫ്റ്റുകൾ നിങ്ങൾക്ക് സേവ് ചെയ്യാം &mdash; തടയപ്പെടുന്നതിനുപകരം "this workflow has no actions yet" എന്ന ഒരു മൃദുവായ മുന്നറിയിപ്പ് നിങ്ങൾക്ക് ലഭിക്കും.',
        'testing_dry_heading' => 'Dry run &mdash; അത് ചെയ്യാതെ എന്ത് ചെയ്യുമെന്ന് കാണുക',
        'testing_dry_body' => '<strong>Dry run</strong> കണ്ടീഷനുകൾ യഥാർത്ഥത്തിൽ വിലയിരുത്തുന്നു, എന്നിട്ട് ഓരോ ആക്ഷനും നടപ്പിലാക്കുന്നതിനുപകരം <em>വിവരിക്കുന്നു</em>. <code>{{variables}}</code> ഇതിനകം പൂരിപ്പിച്ചുകൊണ്ട് ഇത് ചെയ്യുമായിരുന്ന ഓരോ ആക്ഷനും ലിസ്റ്റ് ചെയ്ത്, <em>Dry run</em> എന്ന് അടയാളപ്പെടുത്തി റൺ <em>Recent runs</em>-ൽ പ്രത്യക്ഷപ്പെടുന്നു &mdash; അതിനാൽ നിങ്ങൾ യഥാർത്ഥ ഇമെയിൽ വിഷയം, യഥാർത്ഥ ചാറ്റ് മെസ്സേജ്, യഥാർത്ഥ കുറിപ്പ് വായിക്കുന്നു.',
        'testing_dry_safe' => 'ഒന്നും എഴുതുകയോ ഇമെയിൽ ചെയ്യുകയോ ക്യൂ ചെയ്യുകയോ അയയ്ക്കുകയോ ഇല്ല: ടിക്കറ്റ് മാറ്റങ്ങളില്ല, കുറിപ്പുകളില്ല, webhook ഡെലിവറികളില്ല, വർക്ക്ഫ്ലോയുടെ run counter തൊടാതെ തന്നെ നിലനിൽക്കും. അത് ഒരു ലൈവ് വർക്ക്ഫ്ലോയിൽ ചൂണ്ടിക്കാണിക്കാൻ ഇത് സുരക്ഷിതമാക്കുന്നു &mdash; പുതുതായി ക്ലോൺ ചെയ്ത ഒരു ടെംപ്ലേറ്റുമായി ചെയ്യേണ്ട ബുദ്ധിപൂർവ്വമായ ആദ്യ കാര്യമാണിത്. (ഏത് സൈനിംഗ് സീക്രട്ടും ഔട്ട്പുട്ടിൽ echo ചെയ്യപ്പെടാതെ റിഡാക്റ്റ് ചെയ്യപ്പെടും.)',
        'testing_log_heading' => 'എക്സിക്യൂഷൻ ലോഗ് &mdash; യഥാർത്ഥത്തിൽ എന്ത് സംഭവിച്ചു',
        'testing_log_body' => 'ഓരോ വർക്ക്ഫ്ലോയുടെയും ഓരോ റണ്ണും (Workflows ഹെഡറിലെ) <strong>Execution log</strong>-ൽ എത്തുന്നു. workflow, status, trigger, date അല്ലെങ്കിൽ ഫ്രീ ടെക്സ്റ്റ് പ്രകാരം ഫിൽട്ടർ ചെയ്യുക, എഞ്ചിൻ എന്ത് ചെയ്തു എന്ന് <strong>സ്റ്റെപ്പ് ബൈ സ്റ്റെപ്പ്</strong> കാണാൻ ഏത് റൺ വേണമെങ്കിലും തുറക്കുക &mdash; ഏത് കണ്ടീഷൻ പൊരുത്തപ്പെട്ടു, ഏത് പൊരുത്തപ്പെട്ടില്ല (അത് താരതമ്യം ചെയ്ത <em>യഥാർത്ഥ മൂല്യം</em> സഹിതം), ഓരോ ആക്ഷനും എന്ത് തിരികെ നൽകി അല്ലെങ്കിൽ എങ്ങനെ പരാജയപ്പെട്ടു, <strong>ട്രിഗ്ഗർ പേലോഡ് സ്നാപ്ഷോട്ട്</strong>: കണ്ടീഷനുകൾ എന്തിനെതിരെയാണ് പരിശോധിച്ചത്, <code>{{variables}}</code> എന്തിൽ നിന്നാണ് പരിഹരിച്ചത് എന്നും, റൺ സമയത്ത് പകർത്തിയത്.',
        'testing_log_why' => 'ഇത് തോന്നുന്നതിനേക്കാൾ പ്രധാനമാണ്. എഞ്ചിൻ <strong>മനഃപൂർവ്വം സ്വന്തം പിശകുകൾ വിഴുങ്ങുന്നു</strong> &mdash; ഒരു തകർന്ന വർക്ക്ഫ്ലോ അതിനെ ട്രിഗർ ചെയ്ത ടിക്കറ്റ് സേവ് ഒരിക്കലും തകർക്കരുത്. അത് ശരിയായ തീരുമാനമാണ്, പരാജയപ്പെടുന്ന ഒരു വർക്ക്ഫ്ലോ അല്ലാത്തപക്ഷം <em>പൂർണ്ണമായും നിശബ്ദമാണ്</em> എന്നാണ് അതിനർത്ഥം. ഒന്നും നിങ്ങളോട് പറയില്ല. execution log-ഉം, (കഴിഞ്ഞ 24 മണിക്കൂറിൽ പരാജയങ്ങൾ, loop-protection abort-കൾ, റിട്രൈ ഉപേക്ഷിച്ച webhook-കൾ എന്നിവ ഉയർത്തിക്കാട്ടുന്ന) <strong>Watchtower-ലെ Workflows കാർഡും</strong> ആണ് ആ നിശബ്ദത തകർക്കുന്നത്.',
        'testing_fire_heading' => 'Test fire &mdash; യഥാർത്ഥത്തിൽ ഇത് റൺ ചെയ്യുക',
        'testing_fire' => '<strong>Test fire</strong> അതിന്റെ സ്വന്തം കണ്ടീഷനുകളിൽ നിന്ന് സൃഷ്ടിച്ച ഒരു സിന്തറ്റിക് പേലോഡുമായി വർക്ക്ഫ്ലോ യഥാർത്ഥത്തിൽ റൺ ചെയ്യുന്നു, അതിനാൽ ആക്ഷൻ പാത്ത് യഥാർത്ഥത്തിൽ എക്സിക്യൂട്ട് ചെയ്യുന്നു &mdash; ഇത് ആ ഇമെയിൽ ശരിക്കും അയയ്ക്കും. ഫലം status (<em>success / failed / skipped</em>), പൂർണ്ണ step log എന്നിവയോടെ <em>Recent runs</em>-ൽ എത്തുന്നു.',
        'testing_real' => 'യഥാർത്ഥ ഡാറ്റയ്‌ക്കെതിരെ ടെസ്റ്റ് ചെയ്യാൻ, അതിനെ ട്രിഗർ ചെയ്യുന്ന കാര്യം ചെയ്യുക &mdash; ഒരു ടിക്കറ്റ് അസൈൻ ചെയ്യുക, അതിന്റെ മുൻഗണന മാറ്റുക, തുടങ്ങിയവ. ഹോസ്റ്റ് മൊഡ്യൂളിൽ (Tickets) നിന്നുള്ള dispatch ലൈവ് ആണ്; execution log ഓരോ ഫയറും കാണിക്കുന്നു.',
        'triggers_heading' => 'ട്രിഗ്ഗർ കാറ്റലോഗ്',
        'triggers_intro' => 'കാറ്റലോഗ് ഇപ്പോൾ <strong>ഓരോ മൊഡ്യൂളും &mdash; 138 ട്രിഗ്ഗറുകളും അധികവും</strong> ഉൾക്കൊള്ളുന്നു, എല്ലാം വയർഡ് ആയി ലൈവ് ആണ്. അവ രണ്ട് തരത്തിൽ വരുന്നു:',
        'triggers_time_heading' => 'ടൈം-ബേസ്ഡ് ട്രിഗ്ഗറുകൾ &mdash; അവയ്ക്ക് വേണ്ട ക്രോൺ',
        'triggers_time_body' => 'മിക്ക ട്രിഗ്ഗറുകളും ഒരു <strong>write path</strong>-ൽ നിന്ന് ഫയർ ചെയ്യുന്നു: ആരോ ഒരു ടിക്കറ്റ് സേവ് ചെയ്തു, അതിനാൽ ഫയർ ചെയ്യാൻ ഒരു നിമിഷമുണ്ട്. നാലെണ്ണം അങ്ങനെയല്ല. <code>sla.warning</code>, <code>sla.breached</code>, <code>contract.expiring</code>, <code>asset.warranty_expiring</code> എന്നിവ ഒട്ടും ഇവന്റുകളല്ല &mdash; <em>ഒന്നും സംഭവിച്ചില്ല, സമയം കടന്നുപോയി</em> &mdash; അതിനാൽ ഒരു ഷെഡ്യൂൾഡ് ജോലി അവയെ അന്വേഷിച്ച് പോകേണ്ടതുണ്ട്.',
        'triggers_time_cron' => '<strong>ആ ക്രോണുകൾ ഷെഡ്യൂൾ ചെയ്തിട്ടില്ലെങ്കിൽ, ഈ ട്രിഗ്ഗറുകൾ ഒരിക്കലും ഫയർ ചെയ്യില്ല.</strong> വർക്ക്ഫ്ലോ ആക്ടീവ് ആയി, ഒന്നും ചെയ്യാതെ അവിടെ ഇരിക്കും. SLA ഇവന്റുകൾ SLA breach-check ക്രോണിൽ നിന്ന് വരുന്നു (ഓരോ 5 മിനിറ്റിലും); expiry ഇവന്റുകൾ <code>cron/workflow_scheduled.php</code>-ൽ നിന്ന് (മണിക്കൂറിലൊരിക്കൽ മതി). സെറ്റപ്പ്: <code>docs/workflow-scheduled-cron-setup.md</code>, അല്ലെങ്കിൽ <a href="https://github.com/edmozley/freeitsm/wiki/Time-Based-Triggers" target="_blank" rel="noopener noreferrer">wiki-യിലെ Time-Based Triggers</a>, ഇത് ഇപ്പോഴും-true ആയ ഒരു കണ്ടീഷൻ (ഒരു ബ്രീച്ച് ചെയ്ത SLA ബ്രീച്ച് ആയി തുടരും) ഓരോ കുറച്ച് മിനിറ്റിലും വീണ്ടും ഫയർ ചെയ്യാത്തത് എന്തുകൊണ്ടെന്നും വിശദീകരിക്കുന്നു.',
        'triggers_time_once' => 'ഒരു ടൈം-ബേസ്ഡ് കണ്ടീഷൻ <strong>true ആയി തുടരും</strong> &mdash; ഒരു ബ്രീച്ച് ചെയ്ത SLA അഞ്ച് മിനിറ്റ് കഴിഞ്ഞും ബ്രീച്ച് ആയി തന്നെ &mdash; അതിനാൽ FreeITSM ഒരു ലെഡ്ജർ സൂക്ഷിക്കുന്നു, ഓരോ സാഹചര്യവും <strong>കൃത്യമായി ഒരിക്കൽ</strong> ഫയർ ചെയ്യുന്നു. അതിനടിയിലുള്ള കാര്യം മാറുമ്പോൾ ഇത് വീണ്ടും ആയുധമാകും: ഒരു ടിക്കറ്റിന്റെ മുൻഗണന ഉയർത്തുക, അതിന്റെ SLA ടാർഗെറ്റ് ചുരുങ്ങുന്നു, അതിനാൽ പുതിയ, കൂടുതൽ കർശനമായ ഡെഡ്‌ലൈൻ വീണ്ടും എസ്കലേറ്റ് ചെയ്യാൻ അനുവദിക്കുന്നു. ഒരു കരാർ പുതുക്കുക, അടുത്ത വർഷത്തെ ഓർമ്മപ്പെടുത്തലുകൾ ഇപ്പോഴും ഫയർ ചെയ്യും. Expiries <code>window_days</code> വഹിച്ചുകൊണ്ട് <strong>90, 30, 7, 1 ദിവസങ്ങൾ</strong> മുമ്പ് ഫയർ ചെയ്യുന്നു &mdash; അതിനാൽ "only remind me at 30 days" വെറും ഒരു കണ്ടീഷൻ മാത്രമാണ്.',
        'triggers_family_domain' => '<strong>Rich domain events</strong> &mdash; meaningful lifecycle moments with a full typed payload: <code>ticket.created</code>, <code>ticket.status_changed</code>, <code>change.approved</code>, <code>problem.status_changed</code>, <code>task.completed</code>, <code>service_status.incident_resolved</code>, <code>software.application_discovered</code>, and many more.',
        'triggers_family_forms' => '<strong>ഫോമുകളും കാറ്റലോഗ് അഭ്യർത്ഥനകളും</strong> &mdash; ഒരു സാധാരണ ഫോമിന് <code>form.submitted</code> ഫയർ ചെയ്യുന്നു. അംഗീകാരം ആവശ്യമുള്ള ഒരു ഫോം പകരം <code>catalogue_request.submitted</code> ഫയർ ചെയ്യുന്നു, നിങ്ങളുടെ അപ്രൂവർ തീരുമാനിച്ചുകഴിഞ്ഞാൽ പിന്നെ <code>catalogue_request.approved</code> അല്ലെങ്കിൽ <code>catalogue_request.rejected</code>. പ്രത്യേക ഇവന്റ് മനഃപൂർവ്വമാണ്: സമർപ്പണത്തിൽ ഒരു ടിക്കറ്റ് ഉയർത്തുന്ന ഒരു റൂളിന് നിങ്ങൾ ചോദിച്ച ഒരു അംഗീകാരത്തിന് മുകളിലൂടെ ചവിട്ടാൻ കഴിയില്ല എന്നാണ് ഇതിനർത്ഥം. നാലെണ്ണവും സമർപ്പിച്ച ഉത്തരങ്ങൾ വഹിക്കുന്നു, അതിനാൽ <code>{{submission.fields.Device type}}</code> എല്ലാ ഘട്ടത്തിലും പ്രവർത്തിക്കുന്നു, നാലും ഒരൊറ്റ ഫോമിലേക്ക് ചുരുക്കാം.',
        'triggers_family_crud' => '<strong>Create / update / delete ഇവന്റുകൾ</strong> &mdash; ഓരോ പുനരുപയോഗിക്കാവുന്ന റെക്കോർഡും settings lookup-ഉം <code>&lt;entity&gt;.created</code> / <code>.updated</code> / <code>.deleted</code> emit ചെയ്യുന്നു: tickets, assets, changes, problems, tasks, CMDB, contracts &amp; suppliers, calendar, software licences, network diagrams, അവയുടെ settings ലിസ്റ്റുകൾ (statuses, priorities, types, tags&hellip;) എല്ലാം.',
        'triggers_picker' => 'ലിസ്റ്റ് ഡസൻ കണക്കിന് ആഴമുള്ളതിനാൽ, എഡിറ്ററിന്റെ <strong>trigger picker തിരയാവുന്നതാണ്</strong> &mdash; അത് ഫിൽട്ടർ ചെയ്യാൻ ടൈപ്പ് ചെയ്യാൻ തുടങ്ങുക (<code>resolved</code>, <code>contract</code>, <code>delete</code>&hellip;). ഓരോ ഇവന്റും ഒരു <strong>ഒറ്റ പങ്കിട്ട write path</strong>-ൽ നിന്ന് ഫയർ ചെയ്യുന്നു, അതിനാൽ ബ്രൗസറിൽ നിന്നായാലും, REST API-യിൽ നിന്നായാലും, മറ്റൊരു വർക്ക്ഫ്ലോയിൽ നിന്നായാലും മാറ്റം ഒരേപോലെ പ്രവർത്തിക്കുന്നു &mdash; ഇതിന് വ്യതിചലിക്കാൻ കഴിയില്ല.',
        'failures_heading' => 'എഞ്ചിൻ പരാജയങ്ങൾ ഒറ്റപ്പെട്ടതാണ്',
        'failures_callout' => '<strong>ഒരു ബഗ് ഉള്ള വർക്ക്ഫ്ലോയ്ക്ക് ഹോസ്റ്റ് മൊഡ്യൂളിന്റെ റിക്വസ്റ്റ് തകർക്കാൻ കഴിയില്ല.</strong> ഓരോ dispatch-ഉം ഒരു try/catch-ൽ പൊതിഞ്ഞിരിക്കുന്നു, ഓരോ ആക്ഷന്റെയും പരാജയം ചെയിൻ നിർത്താതെ execution row-ൽ ലോഗ് ചെയ്യുന്നു. ഒരു വർക്ക്ഫ്ലോ നിങ്ങൾ പ്രതീക്ഷിക്കുന്നത് ചെയ്യുന്നത് നിർത്തിയാൽ, വർക്ക്ഫ്ലോയുടെ <em>Recent runs</em> പാനൽ പരിശോധിക്കുക &mdash; അവയെ ട്രിഗർ ചെയ്ത പേജിൽ ഒരു 500 ആയിട്ടല്ല, അടിസ്ഥാന പിശകോടെ പരാജയങ്ങൾ അവിടെ കാണിക്കും.',
        'ahead_heading' => 'ഇനിയും വരാനുള്ളത്',
        'ahead_li1' => '<strong>Tier 3 ആക്ഷനുകൾ</strong> &mdash; Microsoft Graph: <code>graph_add_to_group</code>, <code>graph_assign_license</code>, <code>graph_disable_user</code>. paid ITSM suite-കൾക്കെതിരെ മൊഡ്യൂളിന്റെ നിലനിൽപ്പിനെ ന്യായീകരിക്കുന്ന new-starter / leaver ഓട്ടോമേഷനുകൾ. നിലവിലുള്ള tenant OAuth സ്കാഫോൾഡിംഗ് വീണ്ടും ഉപയോഗിക്കുന്നു.',
        'ahead_li4' => '<strong>Dry-run mode</strong> &mdash; ഒരു യഥാർത്ഥ ഇവന്റിനെതിരെ ഒരു വർക്ക്ഫ്ലോ റൺ ചെയ്യുക, പക്ഷേ ആക്ഷനുകൾ എക്സിക്യൂട്ട് ചെയ്യുന്നതിനുപകരം <em>ലോഗ്</em> ചെയ്യുക. അതിനാൽ ലൈവ് ആക്കുന്നതിന് മുമ്പ് എന്ത് സംഭവിക്കുമായിരുന്നു എന്ന് നിങ്ങൾക്ക് കാണാം.',
        'ahead_li5' => '<strong>Starter recipes</strong> &mdash; clonable templates for the common patterns: new-starter onboarding, P1 incident response, SLA-breach escalation, license-renewal reminder.',
        'ahead_li6' => '<strong>Watchtower integration</strong> &mdash; പരാജയപ്പെട്ട റണ്ണുകൾ attention കാർഡുകളായി ഉയർന്നുവരും.',
        'ahead_li7' => '<strong>Workflow versioning</strong> &mdash; draft / publish / rollback.',
        'ahead_li8' => '<strong>Streaming AI co-author</strong> &mdash; ക്യാൻവാസ് ബിൽഡ് ആകുമ്പോൾ claude.ai-സ്റ്റൈൽ ലൈവ് ഔട്ട്പുട്ട്.',
    ],
];
